#include <pugixml.hpp>
#include <string>

std::string markdown_to_html(const std::string& markdown_text) {
    pugi::xml_document doc;
    pugi::xml_parse_result result = doc.load_string(markdown_text.c_str());

    if (!result) {
        // Handle parsing error
        return "";
    }

    pugi::xml_node root = doc.document_element();
    std::string html_text;
    pugi::xml_print_settings settings;
    settings.m_indent = 0;
    pugi::xml_writer_settings writer_settings;
    writer_settings.m_indent = 0;
    pugi::xml_writer writer(&html_text, writer_settings);
    root.print(writer, settings);

    return html_text;
}
```

